// Host unit tests for the setup phase check. Run with:  pio test -e native -f test_phase_check
// (On Windows the native toolchain is unreliable - run it from WSL.)
// The decisions are replayed from fixtures generated by utils/gen_phase_check_fixtures.py
// out of the reference model utils/phase_solver_ref.py, so the two cannot drift.

#include <unity.h>
#include <stdio.h>
#include <string.h>
#include <cmath>

#include "phase_check.h"
#include "fixtures.h"

using namespace PhaseCheck;

void setUp(void) {}
void tearDown(void) {}

static void assertClose(const Complex &want, const Complex &got, const char *what) {
    const double tol = 1e-6 * (1.0 + std::abs(want));
    char msg[96];
    snprintf(msg, sizeof(msg), "%s: want (%g,%g) got (%g,%g)", what, want.real(), want.imag(), got.real(), got.imag());
    TEST_ASSERT_TRUE_MESSAGE(std::abs(want - got) <= tol, msg);
}

void test_line_decisions_match_reference_model(void) {
    const size_t n = sizeof(LINE_FIXTURES) / sizeof(LINE_FIXTURES[0]);
    for (size_t i = 0; i < n; i++) {
        const LineFixture &f = LINE_FIXTURES[i];
        const Result r = evaluate(f.evidence, static_cast<Phase>(f.voltagePhase), static_cast<ChannelRole>(f.role), f.configured);
        char msg[64];
        snprintf(msg, sizeof(msg), "line case %u", static_cast<unsigned>(i));
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(f.state, static_cast<uint8_t>(r.state), msg);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(f.proposalCount, r.proposalCount, msg);
        for (uint8_t k = 0; k < f.proposalCount; k++) TEST_ASSERT_TRUE_MESSAGE(f.proposals[k] == r.proposals[k], msg);
    }
}

void test_single_decisions_match_reference_model(void) {
    const size_t n = sizeof(SINGLE_FIXTURES) / sizeof(SINGLE_FIXTURES[0]);
    for (size_t i = 0; i < n; i++) {
        const SingleFixture &f = SINGLE_FIXTURES[i];
        ChannelEvidence c{};
        c.ratingA = 30.0;
        c.e = f.e;
        const SingleResult r = checkSingle(c, static_cast<Phase>(f.voltagePhase), static_cast<ChannelRole>(f.role), f.phase, f.reverse);
        char msg[64];
        snprintf(msg, sizeof(msg), "single case %u", static_cast<unsigned>(i));
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(f.state, static_cast<uint8_t>(r.state), msg);
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(f.optionCount, r.optionCount, msg);
        for (uint8_t k = 0; k < f.optionCount; k++) {
            TEST_ASSERT_EQUAL_UINT8_MESSAGE(f.options[k].phase, r.options[k].phase, msg);
            TEST_ASSERT_EQUAL_MESSAGE(f.options[k].reverse, r.options[k].reverse, msg);
        }
    }
}

void test_minute_accumulation_matches_reference_model(void) {
    LineEvidence g{};
    for (auto &c : g.ch) c.ratingA = 30.0;
    const size_t n = sizeof(ACC_READ) / sizeof(ACC_READ[0]);
    for (size_t m = 0; m < n; m++) g.addMinute(ACC_MINUTES[m], ACC_READ[m]);
    for (int i = 0; i < 3; i++) {
        assertClose(ACC_EXPECTED.ch[i].e, g.ch[i].e, "channel e");
        assertClose(ACC_EXPECTED.ch[i].axial, g.ch[i].axial, "channel axial");
        TEST_ASSERT_TRUE(ACC_EXPECTED.ch[i].minutes == g.ch[i].minutes);
    }
    for (int k = 0; k < 3; k++) {
        assertClose(ACC_EXPECTED.pair[k].d, g.pair[k].d, "pair d");
        TEST_ASSERT_TRUE(ACC_EXPECTED.pair[k].minutes == g.pair[k].minutes);
    }
}

void test_minute_bucket_is_not_biased_by_read_rate(void) {
    // Same power, channel 0 read every 200 ms, a multiplexed channel every 800 ms.
    MinuteBucket fast, slow;
    const Complex va{1500.0, 400.0};
    fast.add(va, 0);  // first reading only sets the base
    for (int i = 0; i < 300; i++) fast.add(va, 200);
    for (int i = 0; i < 75; i++) slow.add(va, 800);
    TEST_ASSERT_TRUE(fast.read() && slow.read());
    assertClose(fast.average(), slow.average(), "average");
    assertClose(va, fast.average(), "value");
    MinuteBucket none;
    none.add(va, 0);
    TEST_ASSERT_FALSE(none.read());
}

static Result fixResult(uint8_t phase0) {
    Result r{};
    r.state = State::Fix;
    r.proposalCount = 1;
    r.proposals[0] = Hypothesis{{phase0, 2, 3}, {false, true, false}};
    return r;
}

void test_stable_verdict_needs_two_agreeing_minutes(void) {
    StableVerdict v;
    TEST_ASSERT_FALSE(v.push(fixResult(1), false));
    TEST_ASSERT_EQUAL(State::Collecting, v.shown().state);
    TEST_ASSERT_TRUE(v.push(fixResult(1), false));
    TEST_ASSERT_EQUAL(State::Fix, v.shown().state);
    // A different answer must hold twice before it replaces the shown one.
    TEST_ASSERT_FALSE(v.push(fixResult(2), false));
    TEST_ASSERT_EQUAL_UINT8(1, v.shown().proposals[0].phase[0]);
}

void test_stable_verdict_after_config_write_is_immediate(void) {
    StableVerdict v;
    Result ok{};
    ok.state = State::Verified;
    TEST_ASSERT_TRUE(v.push(ok, true));
    TEST_ASSERT_EQUAL(State::Verified, v.shown().state);
}

void test_stable_verdict_collecting_is_immediate(void) {
    StableVerdict v;
    v.push(fixResult(1), false);
    v.push(fixResult(1), false);
    Result c{};
    TEST_ASSERT_TRUE(v.push(c, false));
    TEST_ASSERT_EQUAL(State::Collecting, v.shown().state);
}

static ChannelView view(bool active, ChannelRole role, uint32_t phase, const char *label) {
    return ChannelView{active, role, phase, label};
}

void test_detect_new_line(void) {
    ChannelView ch[6] = {
        view(true, CHANNEL_ROLE_GRID, 1, "Grid"), view(true, CHANNEL_ROLE_LOAD, 1, "Plant"), view(true, CHANNEL_ROLE_LOAD, 2, "Plant"),
        view(true, CHANNEL_ROLE_LOAD, 3, "Plant"), view(true, CHANNEL_ROLE_LOAD, 1, "Oven"), view(false, CHANNEL_ROLE_LOAD, 2, "Oven"),
    };
    LineId out[4];
    TEST_ASSERT_EQUAL_size_t(1, detectLines(ch, 6, nullptr, 0, out, 4));
    TEST_ASSERT_EQUAL_UINT8(1, out[0].ch[0]);
    TEST_ASSERT_EQUAL_UINT8(3, out[0].ch[2]);
}

void test_line_needs_three_phases_and_one_role(void) {
    ChannelView twoEqual[3] = {view(true, CHANNEL_ROLE_LOAD, 1, "A"), view(true, CHANNEL_ROLE_LOAD, 1, "A"), view(true, CHANNEL_ROLE_LOAD, 3, "A")};
    ChannelView mixedRole[3] = {view(true, CHANNEL_ROLE_LOAD, 1, "A"), view(true, CHANNEL_ROLE_PV, 2, "A"), view(true, CHANNEL_ROLE_LOAD, 3, "A")};
    ChannelView split[3] = {view(true, CHANNEL_ROLE_LOAD, 1, "A"), view(true, CHANNEL_ROLE_LOAD, 4, "A"), view(true, CHANNEL_ROLE_LOAD, 3, "A")};
    LineId out[2];
    TEST_ASSERT_EQUAL_size_t(0, detectLines(twoEqual, 3, nullptr, 0, out, 2));
    TEST_ASSERT_EQUAL_size_t(0, detectLines(mixedRole, 3, nullptr, 0, out, 2));
    TEST_ASSERT_EQUAL_size_t(0, detectLines(split, 3, nullptr, 0, out, 2));
}

void test_line_survives_a_phase_swap_one_channel_at_a_time(void) {
    // L1 and L3 exchanged one write at a time passes through L3, L2, L3.
    ChannelView mid[3] = {view(true, CHANNEL_ROLE_LOAD, 3, "A"), view(true, CHANNEL_ROLE_LOAD, 2, "A"), view(true, CHANNEL_ROLE_LOAD, 3, "A")};
    LineId prev[1] = {{{0, 1, 2}}};
    LineId out[2];
    TEST_ASSERT_EQUAL_size_t(0, detectLines(mid, 3, nullptr, 0, out, 2));
    TEST_ASSERT_EQUAL_size_t(1, detectLines(mid, 3, prev, 1, out, 2));
}

void test_line_dissolves_when_a_channel_leaves(void) {
    ChannelView left[3] = {view(true, CHANNEL_ROLE_LOAD, 1, "A"), view(true, CHANNEL_ROLE_LOAD, 2, "B"), view(true, CHANNEL_ROLE_LOAD, 3, "A")};
    ChannelView fourth[4] = {view(true, CHANNEL_ROLE_LOAD, 1, "A"), view(true, CHANNEL_ROLE_LOAD, 2, "A"), view(true, CHANNEL_ROLE_LOAD, 3, "A"), view(true, CHANNEL_ROLE_LOAD, 1, "A")};
    LineId prev[1] = {{{0, 1, 2}}};
    LineId out[2];
    TEST_ASSERT_EQUAL_size_t(0, detectLines(left, 3, prev, 1, out, 2));
    TEST_ASSERT_EQUAL_size_t(0, detectLines(fourth, 4, prev, 1, out, 2));
}

int main(int, char **) {
    UNITY_BEGIN();
    RUN_TEST(test_line_decisions_match_reference_model);
    RUN_TEST(test_single_decisions_match_reference_model);
    RUN_TEST(test_minute_accumulation_matches_reference_model);
    RUN_TEST(test_minute_bucket_is_not_biased_by_read_rate);
    RUN_TEST(test_stable_verdict_needs_two_agreeing_minutes);
    RUN_TEST(test_stable_verdict_after_config_write_is_immediate);
    RUN_TEST(test_stable_verdict_collecting_is_immediate);
    RUN_TEST(test_detect_new_line);
    RUN_TEST(test_line_needs_three_phases_and_one_role);
    RUN_TEST(test_line_survives_a_phase_swap_one_channel_at_a_time);
    RUN_TEST(test_line_dissolves_when_a_channel_leaves);
    return UNITY_END();
}
